import threading
def solve(data):
    lock = threading.Lock()
    shared = {'count':0}
    def increment(times):
        for _ in range(times):
            with lock: shared['count'] += 1
    workers = [threading.Thread(target=increment, args=(times,)) for times in data]
    for thread in workers: thread.start()
    for thread in workers: thread.join()
    return shared['count']
